ALTER FUNCTION public.save_foundation_settings(jsonb) SECURITY INVOKER; CREATE OR REPLACE FUNCTION public.save_foundation_settings(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT public.private_access() THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; UPDATE public.profiles SET name=left(trim(payload->>'name'),100), timezone=payload->>'timezone' WHERE id=auth.uid(); UPDATE public.settings SET timezone=payload->>'timezone', products_per_day=(payload->>'products_per_day')::integer, daily_post_limit=(payload->>'daily_post_limit')::integer, window_start=(payload->>'window_start')::time, window_end=(payload->>'window_end')::time, min_interval_minutes=(payload->>'min_interval_minutes')::integer, story_delay_min_hours=(payload->>'story_delay_min_hours')::integer, story_delay_max_hours=(payload->>'story_delay_max_hours')::integer, repeat_days=(payload->>'repeat_days')::integer, max_attempts=(payload->>'max_attempts')::integer, min_images=(payload->>'min_images')::integer WHERE user_id=auth.uid(); END $$; GRANT EXECUTE ON FUNCTION public.save_foundation_settings(jsonb) TO authenticated;
CREATE FUNCTION public.audit_settings_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity_log(user_id,action,result) VALUES(NEW.user_id,'Configurações atualizadas','Sucesso'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.audit_settings_change() FROM PUBLIC,anon,authenticated; CREATE TRIGGER settings_audit AFTER UPDATE ON public.settings FOR EACH ROW EXECUTE FUNCTION public.audit_settings_change();